-- Box rewards: every box on the owner's sheet (boxlar.xls) becomes breakable at the Box Breaker NPC / Chaotic Generator,
-- and every breakable box also drops the Red Gem pool (main share) next to its own, low-rate rewards.
--
-- Rate model (see docs/BOX_REWARDS.md): the server builds a pool of exchange_item_count1/5 slots per row (cap 10000 slots),
-- so each box gets exactly 10000 slots (= 50000 weight): 8500 slots (85%) Red Gem rewards, keeping the Red Gem relative
-- proportions (merged duplicates, upgraded +N items replaced by their +0 twin), 1500 slots (15%) the box's own rewards.
--
-- Idempotent: all rows of the managed boxes with random_flag IN (1,2,3) are deleted and re-created, generated rows live in the
-- reserved n_index range 2100000000..2100007851 (7852 rows). Rewards added later in ko-admin to a managed box are replaced on a re-run.
-- Other random_flag rows (101 exchange rows used by Kaira/Moira/... NPCs) are never touched.
-- After applying, the game server has to reload the exchange tables (ko-admin 'reload' / restart).
BEGIN;

-- 1) make the boxes breakable (existing columns are kept)
UPDATE item SET countable = 1, effect2 = 251
 WHERE num IN (507294000,508164000,508195000,508196000,508197000,508198000,810209000,810228000,810229000,810235000,810284000,810329000,810342000,810347000,810348000,810349000,810377000,810536000,811038000,814049000,814050000,890083000,890084000,890085000,890086000,890087000,890088000,890089000,890090000,890091000,890102000,890230000,900214000,900348000,900369000,900370000,900577000,900660000,900668000,900669000,900733000,900734000,900735000,900736000,900823000,900824000,910078000,978049000,978053000,999914000)
   AND (effect2 <> 251 OR countable <> 1);

-- 2) drop previous rows of the managed boxes and of the reserved range
DELETE FROM item_exchange
 WHERE random_flag IN (1,2,3)
   AND origin_item_num1 IN (379154000,379155000,379156000,389160000,389161000,389162000,389163000,389164000,389165000,389166000,389196000,389198000,389199000,389201000,389205000,389556000,507184000,507194000,507204000,507284000,508194000,509194000,810341000,810596000,810678000,810943000,810944000,810948000,810949000,810950000,810951000,810952000,811053000,811137000,999915000,507294000,508164000,508195000,508196000,508197000,508198000,810209000,810228000,810229000,810235000,810284000,810329000,810342000,810347000,810348000,810349000,810377000,810536000,811038000,814049000,814050000,890083000,890084000,890085000,890086000,890087000,890088000,890089000,890090000,890091000,890102000,890230000,900214000,900348000,900369000,900370000,900577000,900660000,900668000,900669000,900733000,900734000,900735000,900736000,900823000,900824000,910078000,978049000,978053000,999914000);
DELETE FROM item_exchange WHERE n_index BETWEEN 2100000000 AND 2100007851;

-- 3) new reward rows (n_index, random_flag, box, 1, reward, weight)

-- 4) sanity: every reward exists and every managed box has exactly 50000 weight (10000 slots)
DO $$
DECLARE bad integer;
BEGIN
  SELECT count(*) INTO bad FROM item_exchange e LEFT JOIN item i ON i.num = e.exchange_item_num1
   WHERE e.n_index BETWEEN 2100000000 AND 2100007851 AND i.num IS NULL;
  IF bad <> 0 THEN RAISE EXCEPTION 'box_rewards: % reward items missing from item', bad; END IF;
  SELECT count(*) INTO bad FROM (
    SELECT origin_item_num1 FROM item_exchange WHERE n_index BETWEEN 2100000000 AND 2100007851
     GROUP BY origin_item_num1 HAVING sum(exchange_item_count1) <> 50000) x;
  IF bad <> 0 THEN RAISE EXCEPTION 'box_rewards: % boxes without 50000 total weight', bad; END IF;
  SELECT count(*) INTO bad FROM item WHERE num IN (379154000,379155000,379156000,389160000,389161000,389162000,389163000,389164000,389165000,389166000,389196000,389198000,389199000,389201000,389205000,389556000,507184000,507194000,507204000,507284000,508194000,509194000,810341000,810596000,810678000,810943000,810944000,810948000,810949000,810950000,810951000,810952000,811053000,811137000,999915000,507294000,508164000,508195000,508196000,508197000,508198000,810209000,810228000,810229000,810235000,810284000,810329000,810342000,810347000,810348000,810349000,810377000,810536000,811038000,814049000,814050000,890083000,890084000,890085000,890086000,890087000,890088000,890089000,890090000,890091000,890102000,890230000,900214000,900348000,900369000,900370000,900577000,900660000,900668000,900669000,900733000,900734000,900735000,900736000,900823000,900824000,910078000,978049000,978053000,999914000) AND (effect2 <> 251 OR countable <> 1);
  IF bad <> 0 THEN RAISE EXCEPTION 'box_rewards: % managed boxes not breakable', bad; END IF;
END $$;

COMMIT;
